-- Batch 05: reviewed project facts and matched future catalog; no as-built claims.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='60s';
SET LOCAL application_name='colliers_ai_backfill_20261124_v4';
DO $fill$
DECLARE r record; n int:=0; old_count int; changed int; ev uuid; now_ts timestamptz; read_value jsonb; source_row jsonb; sub_batch int:=5; expected_before int:=86; expected_added int:=14;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtext('ai_building_field_backfill_20261124_v4_100'));
 SELECT count(*) INTO old_count FROM public.audit_logs WHERE action_type='AI_FIELD_FILL' AND details->>'batch_ref'='ai_building_field_backfill_20261124_v4_100';
 IF old_count<>expected_before OR old_count+expected_added>100 THEN RAISE EXCEPTION 'batch sequence guard: %',old_count; END IF;
 -- Serialize the brief data transaction against other writes, not normal reads.
 LOCK TABLE public.buildings,public.building_brochure_data,public.building_data_field_provenance IN SHARE ROW EXCLUSIVE MODE;
 LOCK TABLE public.building_sales_materials,public.future_supplies IN SHARE MODE;
 FOR r IN
 WITH specs AS (SELECT * FROM jsonb_to_recordset($spec$[{"src":"844ba62e-c79a-45dc-8412-509d6479aa03","hash":"ea820b98c359ba8d91e23b49cd48a029152ae2cfbadad7e00bf55088458a02fa","label":"Z3东环捌号（CBD核心区Z3项目） · P35/1","f":"gfa_total","type":"numeric","unit":"m2","pat":"总建面约([0-9.]+)万㎡","mult":10000,"note":"future supply; approximate historical design total GFA (not office or leasable area); corroborated by other reviewed Z3 version"},{"src":"844ba62e-c79a-45dc-8412-509d6479aa03","hash":"ea820b98c359ba8d91e23b49cd48a029152ae2cfbadad7e00bf55088458a02fa","label":"Z3东环捌号（CBD核心区Z3项目） · P35/3","f":"efficiency_rate","type":"numeric","unit":"percent","pat":"标准层使用率约([0-9]+)%","mult":1,"note":"future supply; approximate design standard-floor efficiency, not as-built measurement"},{"src":"51c41d6a-0a62-4531-a195-ae76cd0e27a2","hash":"08c4fb35fb4490f3edaf51813ae27c46f23dd8aebd1dc30965f0a61d6b48a825","label":"Z3东环捌号（CBD核心区Z3项目） · P35/3","f":"telecom_provider","type":"text","unit":"provider_names","pat":"原页列(联通、电信、移动)三家","mult":1,"note":"future supply historical planned telecom provision, not claim of active service"},{"src":"413df196-ed04-41c9-a2e6-8833765bbced","hash":"bc42d3b56e44074a1cb205e9c274b7c7aeaacef4b1b8340c0f874e02b89ba231","label":"Vision Place维晟中心（远洋Z6） · P12/1","f":"well_certification","type":"text","unit":"historical_certification_label","pat":"(WELL中期认证)","mult":1,"note":"future supply; interim certification as archived, not final certification or independently checked current status"},{"src":"c9a2fb6b-ceb0-5272-836b-11c9dacc6ea8","hash":"3672335053df0af61c8b52ae4c5cc25c8576b2523d18c1b68b234b312d476cea","label":"国家金融信息大厦功能方案 · 原文参数1","f":"elevator_zones","type":"text","unit":"configuration","pat":"(高/中/次低/低区共28主客梯，摆渡2×2另计)","mult":1,"note":"reviewed historical design; main passenger count agrees with existing 28, transfer elevators distinct"}]$spec$::jsonb) v(src uuid,hash text,label text,f text,type text,unit text,pat text,mult numeric,note text)), c AS (
 SELECT b.id bid,b.name,d.id target_id,v.f field_name,CASE WHEN v.type='numeric' THEN to_jsonb(m.val::numeric*v.mult) ELSE to_jsonb(m.val) END new_value,v.type value_type,'building_sales_materials' source_table,s.id source_id,v.label source_field,'internal_project_fact' source_kind,v.unit,v.note||'; source_sha256='||v.hash note
 FROM specs v JOIN public.building_sales_materials s ON s.id=v.src AND s.source_sha256=v.hash JOIN public.buildings b ON b.id=s.building_id JOIN public.building_brochure_data d ON d.building_id=b.id CROSS JOIN LATERAL jsonb_array_elements(s.project_facts) x CROSS JOIN LATERAL (SELECT (regexp_match(x->>'value',v.pat))[1] val) m
 WHERE s.status='ready' AND s.association_status='confirmed' AND s.extraction->'extraction'->>'reviewed'='true' AND x->>'label'=v.label AND m.val IS NOT NULL AND b.is_active AND b.city IN ('北京','北京市') AND b.tracking_scope='tracked' AND b.merged_into_id IS NULL AND ((b.project_type='stock' AND v.f='elevator_zones' AND d.elevator_passenger=28) OR (b.project_type='future' AND b.is_entered_market IS FALSE)) AND to_jsonb(d)->v.f='null'::jsonb AND (SELECT count(*) FROM public.building_brochure_data z WHERE z.building_id=b.id)=1
 UNION ALL
 SELECT b.id,b.name,d.id,f.field_name,to_jsonb(f.new_value),'text','buildings',b.id,f.field_name,'internal_future_catalog_sync','category','same canonical future project ID; matches future_supplies classification; not declaration of completed project'
 FROM public.buildings b JOIN public.building_brochure_data d ON d.building_id=b.id JOIN public.future_supplies s ON s.building_id=b.id AND s.district=b.district AND s.submarket=b.submarket CROSS JOIN LATERAL (VALUES ('district',b.district),('submarket',b.submarket)) f(field_name,new_value)
 WHERE b.project_type='future' AND b.is_active AND b.city IN ('北京','北京市') AND b.tracking_scope='tracked' AND b.merged_into_id IS NULL AND b.is_entered_market IS FALSE AND to_jsonb(d)->f.field_name='null'::jsonb AND nullif(trim(f.new_value),'') IS NOT NULL AND (SELECT count(*) FROM public.building_brochure_data z WHERE z.building_id=b.id)=1 AND (SELECT count(*) FROM public.future_supplies z WHERE z.building_id=b.id)=1
 ) SELECT c.* FROM c WHERE NOT EXISTS (SELECT 1 FROM public.building_data_field_provenance p WHERE p.building_id=c.bid AND p.target_table='building_brochure_data' AND p.field_name=c.field_name) AND NOT EXISTS (SELECT 1 FROM public.audit_logs a WHERE a.action_type='AI_FIELD_FILL' AND a.target_table='building_brochure_data' AND a.target_id=c.target_id::text AND (a.details->>'field_name'=c.field_name OR a.new_values ? c.field_name)) ORDER BY target_id,field_name
 LOOP
  IF r.new_value IS NULL OR r.new_value='null'::jsonb OR r.value_type NOT IN ('text','integer','numeric','boolean','date') THEN RAISE EXCEPTION 'invalid candidate'; END IF;
  ev:=gen_random_uuid(); now_ts:=clock_timestamp();
  EXECUTE format('UPDATE public.building_brochure_data SET %I=($2#>>''{}'')::%s WHERE id=$1 AND building_id=$3 AND %I IS NULL',r.field_name,r.value_type,r.field_name) USING r.target_id,r.new_value,r.bid;
  GET DIAGNOSTICS changed=ROW_COUNT;
  IF changed<>1 THEN RAISE EXCEPTION 'null protection failed'; END IF;
  INSERT INTO public.building_data_field_provenance(building_id,brochure_data_id,target_table,field_name,field_value,source_type,source_tier,source_name,source_retrieved_at,value_recorded_at,verification_status,evidence_group_id,evidence_note,is_current)
  VALUES(r.bid,r.target_id,'building_brochure_data',r.field_name,r.new_value,CASE WHEN r.source_kind='internal_project_fact' THEN 'brochure' ELSE 'other' END,CASE WHEN r.source_kind='internal_project_fact' THEN 'secondary' ELSE 'legacy_unknown' END,CASE WHEN r.source_kind='internal_project_fact' THEN '高力国际已审阅历史项目资料' ELSE '高力国际内部已有业务记录' END,now_ts,now_ts,'legacy_backfill',ev,'batch_ref=ai_building_field_backfill_20261124_v4_100; source_table='||r.source_table||'; source_record_id='||r.source_id||'; source_field='||r.source_field||'; unit='||r.unit||'; '||r.note||'; AI-assisted',true);
  INSERT INTO public.audit_logs(id,user_id,action_type,details,request_source,module,target_table,target_id,target_name,old_values,new_values,event_id,occurred_at,actor_kind,actor_name)
  VALUES(nextval('public.audit_logs_id_seq'),'codex','AI_FIELD_FILL',jsonb_build_object('batch_ref','ai_building_field_backfill_20261124_v4_100','sub_batch',sub_batch,'building_id',r.bid,'field_name',r.field_name,'source_table',r.source_table,'source_record_id',r.source_id,'source_field',r.source_field,'source_kind',r.source_kind,'unit',r.unit,'verification_status','legacy_backfill','evidence_group_id',ev,'ai_assisted',true,'reversible',true),'codex_mcp','building_brochure_data','building_brochure_data',r.target_id::text,r.name,jsonb_build_object(r.field_name,NULL),jsonb_build_object(r.field_name,r.new_value),'ai_field_fill:'||ev::text,now_ts,'tool','Codex（工具执行）');
  EXECUTE format('SELECT to_jsonb(%I) FROM public.building_brochure_data WHERE id=$1',r.field_name) INTO read_value USING r.target_id;
  IF read_value IS DISTINCT FROM r.new_value OR NOT EXISTS(SELECT 1 FROM public.building_data_field_provenance p JOIN public.audit_logs a ON a.event_id='ai_field_fill:'||ev::text WHERE p.evidence_group_id=ev AND p.is_current AND p.field_value=read_value AND a.new_values->r.field_name=p.field_value AND a.old_values->r.field_name='null'::jsonb) THEN RAISE EXCEPTION 'readback failed'; END IF;
  n:=n+1;
 END LOOP;
 IF n<>expected_added THEN RAISE EXCEPTION 'expected % qualifying fields, got %',expected_added,n; END IF;
END $fill$;
SELECT count(*) cumulative,count(distinct (target_table,target_id,details->>'field_name')) unique_fields FROM public.audit_logs WHERE action_type='AI_FIELD_FILL' AND details->>'batch_ref'='ai_building_field_backfill_20261124_v4_100';
COMMIT;